local DominoMaker = {}
local PRODUCTS = {
    bone_domino = { name = "Kostne domine", boneCost = 2, inkCost = 1, time = 2, cost = 20, artistry = 40, happiness = 2, description = "Kostne domine za preproste igre." },
    ivory_domino = { name = "Slonokoščene domine", ivoryCost = 1, inkCost = 1, time = 3, cost = 50, artistry = 55, prestige = 2, happiness = 3, description = "Slonokoščene domine za trgovce." },
    painted_domino = { name = "Poslikane domine", ivoryCost = 1, inkCost = 1, paintCost = 1, time = 5, cost = 120, artistry = 70, prestige = 5, happiness = 4, description = "Poslikane domine z barvnimi pikami." },
    silver_pip_domino = { name = "Srebrnopikčaste domine", ivoryCost = 1, silverCost = 1, inkCost = 1, paintCost = 1, time = 7, cost = 280, artistry = 82, prestige = 10, happiness = 5, description = "Domine s srebrnimi pikami za plemiče." },
    gold_inlaid_domino = { name = "Zlatointarzirane domine", ivoryCost = 1, goldCost = 1, silverCost = 1, jewelCost = 1, inkCost = 1, time = 10, cost = 600, artistry = 92, prestige = 18, happiness = 7, description = "Zlatointarzirane domine za visoke plemiče." },
    royal_grand_domino = { name = "Kraljevski veliki domine", ivoryCost = 2, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, inkCost = 1, time = 15, cost = 1600, artistry = 100, prestige = 40, happiness = 12, description = "Velike kraljevske domine z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Dominarska delavnica", cost = { gold = 260, wood = 120, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    carving_room = { name = "Rezbarnica", cost = { gold = 850, wood = 220, stone = 400, bone = 8 }, upkeep = 21, qualityBonus = 18 },
    inlay_room = { name = "Intarzijalnica", cost = { gold = 2200, wood = 350, stone = 600, silver = 25, ivory = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_domino_atelier = { name = "Kraljevski atelje domin", cost = { gold = 9000, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
DominoMaker.boneStock = 12; DominoMaker.ivoryStock = 10; DominoMaker.inkStock = 14; DominoMaker.paintStock = 12; DominoMaker.silverStock = 8; DominoMaker.goldStock = 6; DominoMaker.jewelStock = 6; DominoMaker.pearlStock = 4
DominoMaker.productStock = {}; DominoMaker.buildings = {}; DominoMaker.maker = nil; DominoMaker.activeMaking = {}; DominoMaker.totalProducts = 0; DominoMaker.dayTimer = 0
function DominoMaker.init() DominoMaker.boneStock=12; DominoMaker.ivoryStock=10; DominoMaker.inkStock=14; DominoMaker.paintStock=12; DominoMaker.silverStock=8; DominoMaker.goldStock=6; DominoMaker.jewelStock=6; DominoMaker.pearlStock=4; DominoMaker.productStock={}; DominoMaker.buildings={}; DominoMaker.maker=nil; DominoMaker.activeMaking={}; DominoMaker.totalProducts=0; DominoMaker.dayTimer=0; print("[DominoMaker] Royal Domino Maker System initialized (6 products, 4 buildings)") end
function DominoMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; DominoMaker.maker={name=n or ("Dominar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dominar najet: %s (spretnost: %d)",DominoMaker.maker.name,s),"success") end; return true end
function DominoMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function DominoMaker.build(id) local ok,e=DominoMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(DominoMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function DominoMaker.getQualityBonus() local b=0; for _,bd in ipairs(DominoMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function DominoMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.boneCost and DominoMaker.boneStock<(d.boneCost or 0) then return false,"Premalo kosti" end; if d.ivoryCost and DominoMaker.ivoryStock<(d.ivoryCost or 0) then return false,"Premalo slonovine" end; if d.inkCost and DominoMaker.inkStock<(d.inkCost or 0) then return false,"Premalo črnila" end; if d.paintCost and DominoMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and DominoMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and DominoMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and DominoMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and DominoMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #DominoMaker.buildings==0 then return false,"Potrebna delavnica" end; if not DominoMaker.maker then return false,"Potreben dominar" end; return true end
function DominoMaker.make(pt,qty) qty=qty or 1; local ok,e=DominoMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.boneCost then DominoMaker.boneStock=DominoMaker.boneStock-d.boneCost*qty end; if d.ivoryCost then DominoMaker.ivoryStock=DominoMaker.ivoryStock-d.ivoryCost*qty end; if d.inkCost then DominoMaker.inkStock=DominoMaker.inkStock-d.inkCost*qty end; if d.paintCost then DominoMaker.paintStock=DominoMaker.paintStock-d.paintCost*qty end; if d.silverCost then DominoMaker.silverStock=DominoMaker.silverStock-d.silverCost*qty end; if d.goldCost then DominoMaker.goldStock=DominoMaker.goldStock-d.goldCost*qty end; if d.jewelCost then DominoMaker.jewelStock=DominoMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then DominoMaker.pearlStock=DominoMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if DominoMaker.maker then t=math.max(1,t-math.floor(DominoMaker.maker.skill/12)) end; table.insert(DominoMaker.activeMaking,{id="domino_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,artistry=d.artistry or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function DominoMaker.completeMaking(m) local q=1.0+(DominoMaker.getQualityBonus()/100); if DominoMaker.maker then q=q+(DominoMaker.maker.skill/180) end; q=math.min(2.0,q); DominoMaker.productStock[m.productType]=(DominoMaker.productStock[m.productType] or 0)+m.quantity; DominoMaker.totalProducts=DominoMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if DominoMaker.maker then DominoMaker.maker.itemsMade=DominoMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then DominoMaker.maker.skill=math.min(100,DominoMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Domine izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"domino.completed",{productName=m.productName,artistry=m.artistry,prestige=m.prestige,happiness=m.happiness}) end end
function DominoMaker.update(dt) if not _G.state then return end; DominoMaker.dayTimer=DominoMaker.dayTimer+dt; if DominoMaker.dayTimer>=30 then DominoMaker.dayTimer=0; for i=#DominoMaker.activeMaking,1,-1 do local m=DominoMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then DominoMaker.completeMaking(m); table.remove(DominoMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(DominoMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if DominoMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function DominoMaker.getStats() return {boneStock=DominoMaker.boneStock,ivoryStock=DominoMaker.ivoryStock,inkStock=DominoMaker.inkStock,paintStock=DominoMaker.paintStock,silverStock=DominoMaker.silverStock,goldStock=DominoMaker.goldStock,jewelStock=DominoMaker.jewelStock,pearlStock=DominoMaker.pearlStock,productStock=DominoMaker.productStock,numBuildings=#DominoMaker.buildings,hasMaker=DominoMaker.maker~=nil,makerName=DominoMaker.maker and DominoMaker.maker.name or "—",makerSkill=DominoMaker.maker and DominoMaker.maker.skill or 0,activeMaking=#DominoMaker.activeMaking,totalProducts=DominoMaker.totalProducts} end
return DominoMaker
